package com.sathavahana.kalamkari.controller; import com.sathavahana.kalamkari.dto.CartDto; import com.sathavahana.kalamkari.service.CartService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/cart") public class CartController {private final CartService service; public CartController(CartService s){service=s;} public record Add(@NotNull Long productId,@Min(1) int quantity){} @GetMapping public CartDto get(){return service.get();} @PostMapping("/items") public CartDto add(@Valid @RequestBody Add a){return service.add(a.productId(),a.quantity());}}
